import {DEFAULT_PROJECT,cloneProject,validateProject,resolveCardBackground,readSavedProject,writeSavedProject,listVariants,saveVariant,deleteVariant} from './model.js';
import {FONT_CATALOG,EXTRA_BASE_FONTS,loadFont,registerCustomFont} from './fonts.js';
import {captureText,morphText,cancelTextMorph} from './morph.js';
import {screenDeltaToLocal,clampOffset} from './layout.js';

const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ROLES=['primary','secondary','tertiary'];
const ROLE_NAMES={primary:'Principal',secondary:'Secundaria',tertiary:'Terciaria'};
const COLOR_NAMES={primary:'Primario',secondary:'Secundario',tertiary:'Terciario'};
const SHEETS=[{id:'type',name:'Sistema tipográfico',short:'Sistema',image:null},{id:'cards',name:'Tarjetas personales',short:'Tarjetas',image:'cards'},{id:'stationery',name:'Papelería de estudio',short:'Papelería',image:'stationery'},{id:'sign',name:'Cartel de obra',short:'Obra',image:'sign'},{id:'facade',name:'Señalética de fachada',short:'Fachada',image:'facade'}];
const TEXT_LABELS={brand:'Nombre de la marca',cardBackBrand:'Marca · dorso de tarjeta',tagline:'Actividad / descriptor',claim:'Frase de marca',email:'Correo electrónico',phone:'Teléfono',website:'Sitio web',projectCode:'Código de proyecto',planCode:'Código de plano',address:'Ubicación',letterTitle:'Título de la carta',letterBody:'Texto de la carta',sheetTitle:'Título de lámina',edition:'Edición',footer:'Pie de lámina',cardsTitle:'Título de tarjetas',stationeryTitle:'Título de papelería',facadeTitle:'Título de fachada',specimenPrimary:'Caracteres · principal',specimenSecondary:'Caracteres · secundaria',specimenTertiary:'Caracteres · terciaria',primaryUsage:'Uso · principal',secondaryUsage:'Uso · secundaria',tertiaryUsage:'Uso · terciaria',primaryLabel:'Etiqueta · principal',secondaryLabel:'Etiqueta · secundaria',tertiaryLabel:'Etiqueta · terciaria'};
const PRESETS=[{name:'Original',palette:{primary:'#1A1D1C',secondary:'#F5F4EE',tertiary:'#6F392C'}},{name:'Azul mineral',palette:{primary:'#24272C',secondary:'#F7F8FA',tertiary:'#4473A7'}},{name:'Grafito',palette:{primary:'#20221F',secondary:'#EFF0EA',tertiary:'#8B9385'}}];
let project=cloneProject(),sheet=0,panel='palette',selected=null,zoom=1,toastTimer,saveTimer,saveQueue=Promise.resolve(),mutationVersion=0;
let undoStack=[],redoStack=[],fontPickerRole='primary',fontPreviewObserver=null,renderGeneration=0;
let fontRequests={primary:0,secondary:0,tertiary:0},projectEpoch=0,restoreRequest=0;
let pendingImageSlot='cards',cardView='both',activeCardFace='front',addSurface=null,dragState=null,suppressCanvasClickUntil=0;
// Keep stored surface IDs stable when changing the public names of card faces.
const CARD_SURFACES={front:'cards-back',back:'cards-front'};
const CARD_FACES=['front','back'];
const CARD_FACE_NAMES={front:'Frente',back:'Dorso'};
const SURFACE_NAMES={type:'Lámina tipográfica',cards:'Lámina de tarjetas','cards-front':'Dorso de tarjeta','cards-back':'Frente de tarjeta',stationery:'Lámina de papelería','stationery-paper':'Hoja membretada','stationery-envelope':'Sobre','stationery-ticket':'Etiqueta de proyecto',sign:'Fotografía de obra','sign-panel':'Cartel de obra','sign-footer':'Franja de contacto',facade:'Fotografía de fachada','facade-panel':'Rótulo de fachada'};
const SHEET_SURFACES=[['type'],[CARD_SURFACES.front,CARD_SURFACES.back,'cards'],['stationery-paper','stationery-envelope','stationery-ticket','stationery'],['sign-panel','sign-footer','sign'],['facade-panel','facade']];
const modal=$('#modal');

function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),error?6500:3500);}
function checkpoint(){const value=JSON.stringify(project);if(undoStack.at(-1)!==value){undoStack.push(value);if(undoStack.length>30)undoStack.shift();}redoStack=[];updateHistoryButtons();}
function updateHistoryButtons(){$('[data-action=undo]').disabled=!undoStack.length;$('[data-action=redo]').disabled=!redoStack.length;}
function savedStatus(text,error=false){const el=$('#save-state');el.innerHTML='<i></i>'+esc(text);el.classList.toggle('error',error);el.title=text;}
function scheduleSave(){mutationVersion++;savedStatus('Guardando…');clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,450);}
function flushSave(){clearTimeout(saveTimer);const version=mutationVersion;const current=cloneProject(project);saveQueue=saveQueue.catch(()=>{}).then(()=>writeSavedProject(current)).then(()=>{if(version===mutationVersion)savedStatus('Guardado local');}).catch(error=>{savedStatus('Sin guardar',true);toast('No se pudo guardar: '+error.message+'. Exportá tu proyecto para conservarlo.',true);});return saveQueue;}
function applyTheme(){const root=document.documentElement;for(const role of ROLES){root.style.setProperty('--brand-'+role,project.palette[role]);const f=project.fonts[role];root.style.setProperty('--font-'+role,JSON.stringify(f.family)+','+(role==='tertiary'?'monospace':'Arial,sans-serif'));root.style.setProperty('--weight-'+role,String(f.weight));root.style.setProperty('--tracking-'+role,f.tracking+'px');}$('#motion-toggle').setAttribute('aria-pressed',String(project.motion.enabled));$('#project-name').value=project.name;applyCardTheme();syncCardControls();}
function cardForeground(face,role){
  const background=resolveCardBackground(project,face),original=project.palette[role];
  if(!project.cardAutoContrast||ROLES.includes(project.cardBackgrounds[face])||contrastRatio(original,background)>=4.5)return original;
  const palette=ROLES.map(r=>project.palette[r]).sort((a,b)=>contrastRatio(b,background)-contrastRatio(a,background));
  if(contrastRatio(palette[0],background)>=4.5)return palette[0];
  return contrastRatio('#000000',background)>=contrastRatio('#FFFFFF',background)?'#000000':'#FFFFFF';
}
function cardThemeVariables(){return CARD_FACES.flatMap(face=>[
  ['--card-'+face+'-background',resolveCardBackground(project,face)],
  ...ROLES.map(role=>['--card-'+face+'-'+role,cardForeground(face,role)])
]);}
function applyCardTheme(){for(const [name,value] of cardThemeVariables())document.documentElement.style.setProperty(name,value);}
function syncCardControls(){
  for(const face of CARD_FACES){
    const value=resolveCardBackground(project,face),linked=ROLES.includes(project.cardBackgrounds[face]);
    for(const input of $$('[data-card-color="'+face+'"]')){input.value=value;input.closest('.card-color-swatch').style.background=value;}
    for(const input of $$('[data-card-hex="'+face+'"]'))if(document.activeElement!==input)input.value=value;
    for(const label of $$('[data-card-mode="'+face+'"]'))label.textContent=linked?'Color '+COLOR_NAMES[project.cardBackgrounds[face]].toLocaleLowerCase('es'):'Personalizado';
    for(const button of $$('[data-card-reset="'+face+'"]'))button.disabled=project.cardBackgrounds[face]===DEFAULT_PROJECT.cardBackgrounds[face];
  }
}
function setCardBackground(face,value){project.cardBackgrounds[face]=value;applyCardTheme();syncCardControls();scheduleSave();}
function hexColor(raw){let value=raw.trim();if(!value.startsWith('#'))value='#'+value;if(/^#[0-9a-f]{3}$/i.test(value))value='#'+[...value.slice(1)].map(c=>c+c).join('');return /^#[0-9a-f]{6}$/i.test(value)?value.toUpperCase():null;}
function textData(key){return project.texts[key]||project.customTexts.find(t=>t.id===key);}
function textLabel(key){const t=textData(key);return TEXT_LABELS[key]||(t?.value.trim().slice(0,32)||'Texto nuevo');}
function displayText(key){const value=textData(key)?.value??'';if(key!=='brand'||project.caseMode==='original')return value;return project.caseMode==='lowercase'?value.toLocaleLowerCase('es'):value.toLocaleUpperCase('es');}
function textNode(key,classes='',inverse=false,surface=SHEETS[sheet].id){
  const t=textData(key);if(!t)return '';
  const instance=surface+':'+key,position=project.placements[instance]||{x:0,y:0};
  if(['brand','cardBackBrand','tagline','projectCode','planCode'].includes(key)&&!classes.includes('morph-target'))classes+=' morph-target';
  const logo=project.images.logo;
  if(key==='brand'&&logo.src)return `<div class="brand-image font-primary ${classes.replace(/morph-target|fit-text/g,'')}" data-image="logo" tabindex="0" role="button" aria-label="Editar logotipo" style="--node-scale:${t.scale}"><img src="${esc(logo.src)}" alt="${esc(logo.alt)}" style="object-fit:${logo.fit};object-position:${logo.x}% ${logo.y}%;transform:scale(${logo.zoom})"></div>`;
  let color=t.color;if(inverse&&color==='primary')color='secondary';
  const face=CARD_FACES.find(face=>CARD_SURFACES[face]===surface);
  const colorVariable=face?'--card-'+face+'-'+color:'--brand-'+color;
  return `<div class="text-node font-${t.role} color-${color} ${classes}" data-key="${key}" data-instance="${instance}" data-surface="${surface}" tabindex="0" role="button" aria-label="Editar ${esc(textLabel(key))} · ${esc(SURFACE_NAMES[surface])}" aria-description="Arrastrá para mover. Doble clic para escribir. Flechas para ajustar; Mayús y flechas para mover 10 píxeles." style="--node-scale:${t.scale};--node-align:${t.align};--node-x:${position.x}px;--node-y:${position.y}px;${t.width?'--text-box-width:'+t.width+'px;':''}color:var(${colorVariable});font-family:var(--font-${t.role});font-weight:var(--weight-${t.role});letter-spacing:var(--tracking-${t.role})">${esc(displayText(key))}</div>`;
}
function customTextHTML(surface){return project.customTexts.filter(t=>t.surface===surface).map(t=>textNode(t.id,'custom-text-node',false,surface)).join('');}
function sceneImage(slot){const data=project.images[slot];if(!data?.src)return '';return `<img class="scene-image" src="${esc(data.src)}" alt="${esc(data.alt)}" data-image="${slot}" style="object-fit:${data.fit};object-position:${data.x}% ${data.y}%;transform:scale(${data.zoom})">`;}
function sceneControls(slot){return `<div class="scene-controls"><button data-select-image="${slot}">▧ Editar fondo</button><button data-select-image="logo">＋ Logotipo</button></div>`;}
function fontLabel(role){return `<div class="font-name-label"><span data-font-name="${role}">${esc(project.fonts[role].family)}</span><small>${project.fonts[role].weight}</small></div>`;}
function sheetHTML(index){
  const surface=SHEETS[index].id;
  const t=(key,classes='',inverse=false,target=surface)=>textNode(key,classes,inverse,target);
  let html='';
  switch(index){
    case 0:html=`<div class="sheet-header">${t('sheetTitle')}${t('edition')}</div><div class="type-row"><div class="type-sample">${t('primaryLabel','type-label')}${t('brand','type-brand fit-text morph-target')}${t('primaryUsage','type-usage')}</div><div class="font-spec">${fontLabel('primary')}${t('specimenPrimary','alphabet')}</div></div><div class="type-row"><div class="type-sample">${t('secondaryLabel','type-label')}${t('tagline','type-secondary')}${t('secondaryUsage','type-usage')}</div><div class="font-spec">${fontLabel('secondary')}${t('specimenSecondary','alphabet')}</div></div><div class="type-row"><div class="type-sample">${t('tertiaryLabel','type-label')}<div>${t('projectCode','type-tertiary')}${t('planCode','type-tertiary')}</div>${t('tertiaryUsage','type-usage')}</div><div class="font-spec">${fontLabel('tertiary')}${t('specimenTertiary','alphabet')}</div></div><div class="sheet-footer">${t('footer')}<span>01 / 05</span></div>`;break;
    case 1:html=`${sceneImage('cards')}${t('cardsTitle','scene-caption')}<div class="business-card card-back" data-text-surface="${CARD_SURFACES.back}">${t('cardBackBrand','card-back-brand morph-target',false,CARD_SURFACES.back)}${customTextHTML(CARD_SURFACES.back)}</div><div class="business-card card-front" data-text-surface="${CARD_SURFACES.front}">${t('tagline','back-role',false,CARD_SURFACES.front)}${t('email','back-email',false,CARD_SURFACES.front)}${t('phone','back-phone',false,CARD_SURFACES.front)}<div class="card-line"></div>${t('address','back-address',false,CARD_SURFACES.front)}${customTextHTML(CARD_SURFACES.front)}</div>${sceneControls('cards')}`;break;
    case 2:html=`${sceneImage('stationery')}${t('stationeryTitle','scene-caption')}<div class="stationery-ticket" data-text-surface="stationery-ticket">${t('projectCode','',true,'stationery-ticket')}${t('planCode','',true,'stationery-ticket')}${customTextHTML('stationery-ticket')}</div><div class="letter-paper" data-text-surface="stationery-paper">${t('brand','letter-brand fit-text morph-target',false,'stationery-paper')}${t('tagline','letter-tagline',false,'stationery-paper')}<div class="letter-rule"></div><div class="letter-meta">${t('projectCode','',false,'stationery-paper')}${t('address','',false,'stationery-paper')}</div>${t('letterTitle','letter-title',false,'stationery-paper')}${t('letterBody','letter-body',false,'stationery-paper')}<div class="letter-bottom">${t('email','',false,'stationery-paper')}${t('website','',false,'stationery-paper')}</div>${customTextHTML('stationery-paper')}</div><div class="envelope" data-text-surface="stationery-envelope">${t('brand','envelope-brand fit-text morph-target',true,'stationery-envelope')}${t('tagline','envelope-tagline',true,'stationery-envelope')}<div class="card-line"></div>${t('website','envelope-url',true,'stationery-envelope')}${customTextHTML('stationery-envelope')}</div>${sceneControls('stationery')}`;break;
    case 3:html=`${sceneImage('sign')}<div class="site-sign"><div class="sign-content" data-text-surface="sign-panel">${t('tagline','sign-tagline',false,'sign-panel')}${t('brand','sign-brand fit-text morph-target',false,'sign-panel')}${t('claim','sign-claim',false,'sign-panel')}<div class="sign-accent"></div>${customTextHTML('sign-panel')}</div><div class="sign-footer" data-text-surface="sign-footer">${t('email','sign-email',true,'sign-footer')}${t('phone','sign-phone',true,'sign-footer')}${customTextHTML('sign-footer')}</div></div>${sceneControls('sign')}`;break;
    case 4:html=`${sceneImage('facade')}<div class="facade-panel" data-text-surface="facade-panel">${t('brand','facade-brand fit-text morph-target',false,'facade-panel')}${customTextHTML('facade-panel')}</div>${t('facadeTitle','facade-caption')}${sceneControls('facade')}`;break;
  }
  return html+customTextHTML(surface);
}

function currentAddSurface(){if(addSurface&&SHEET_SURFACES[sheet].includes(addSurface))return addSurface;return sheet===1?CARD_SURFACES[activeCardFace]:SHEET_SURFACES[sheet][0];}
function renderLayoutToolbar(){
  $('#layout-toolbar').innerHTML=`<div class="card-view-controls" role="group" aria-label="Vista de tarjetas personales" ${sheet===1?'':'hidden'}><span>Ver tarjeta</span>${[['both','Ambas'],['front','Frente'],['back','Dorso']].map(([view,label])=>`<button data-card-view="${view}" aria-pressed="${cardView===view}">${label}</button>`).join('')}</div><div class="card-background-controls" role="group" aria-label="Fondos de las tarjetas" ${sheet===1?'':'hidden'}><span>Fondos</span>${CARD_FACES.map(face=>`<label class="card-color-control"><span class="card-color-swatch" style="background:${resolveCardBackground(project,face)}"><input type="color" data-card-color="${face}" aria-label="Fondo del ${CARD_FACE_NAMES[face].toLocaleLowerCase('es')}" value="${resolveCardBackground(project,face)}"></span>${CARD_FACE_NAMES[face]}</label>`).join('')}<button class="card-color-settings" data-action="card-colors">Ajustes</button></div><span class="drag-hint" ${sheet===1?'hidden':''}>Componé tu lámina</span><button class="button outline small add-text-button" data-action="add-text" ${project.customTexts.length>=100?'disabled':''}>＋ Agregar texto</button>`;
}
function setCardView(view){if(!['both','front','back'].includes(view))return;finishTextDrag(true);cardView=view;if(view!=='both')activeCardFace=view;addSurface=null;selected=null;renderBoard();if(panel==='content')renderPanel();}
function getSelectedNode(){return selected?.instance?$(`[data-instance="${CSS.escape(selected.instance)}"]`,$('#artboard')):null;}
function getTextSurface(node){return node?.closest('[data-text-surface]')||$('#artboard');}
function addText(){
  if(project.customTexts.length>=100){toast('Podés agregar hasta 100 cuadros de texto por proyecto.',true);return;}
  finishTextDrag(true);const surface=currentAddSurface(),id='custom-'+crypto.randomUUID();
  if(sheet===1&&surface.startsWith('cards-')&&cardView!=='both')cardView=surface===CARD_SURFACES.front?'front':'back';
  const target=surface===SHEETS[sheet].id?$('#artboard'):$(`[data-text-surface="${surface}"]`,$('#artboard'));
  const width=Math.min(240,Math.max(24,(target?.clientWidth||1000)-48));
  const count=project.customTexts.filter(t=>t.surface===surface).length;
  const face=CARD_FACES.find(face=>CARD_SURFACES[face]===surface);
  const dark=face?contrastRatio(project.palette.primary,resolveCardBackground(project,face))<contrastRatio(project.palette.secondary,resolveCardBackground(project,face)):['stationery-envelope','stationery-ticket','sign-footer'].includes(surface);
  checkpoint();project.customTexts.push({id,surface,value:'Nuevo texto',role:'secondary',color:dark?'secondary':'primary',scale:1,align:'left',width});
  project.placements[surface+':'+id]={x:Math.min(40+(count%5)*18,Math.max(16,(target?.clientWidth||1000)-width-16)),y:Math.min(40+(count%7)*26,Math.max(16,(target?.clientHeight||700)-44))};
  selected={type:'text',key:id,instance:surface+':'+id};panel='content';renderBoard();renderPanel();scheduleSave();$('#text-editor')?.focus();$('#text-editor')?.select();toast('Texto agregado en '+SURFACE_NAMES[surface].toLocaleLowerCase('es')+'.');
}
function deleteSelectedText(){
  if(selected?.type!=='text'||!project.customTexts.some(t=>t.id===selected.key))return;
  checkpoint();const key=selected.key;project.customTexts=project.customTexts.filter(t=>t.id!==key);for(const instance of Object.keys(project.placements))if(instance.endsWith(':'+key))delete project.placements[instance];selected=null;renderBoard();renderPanel();scheduleSave();toast('Cuadro eliminado. Podés deshacer el cambio.');
}

function snapshots(){return $$('.morph-target',$('#artboard')).map(el=>({key:el.dataset.key,instance:el.dataset.instance,snapshot:captureText(el)}));}
function fitText(root){for(const el of $$('.fit-text',root)){el.style.fontSize='';const computed=Number.parseFloat(getComputedStyle(el).fontSize);if(el.scrollWidth>el.clientWidth&&el.clientWidth>0)el.style.fontSize=Math.max(8,computed*(el.clientWidth/el.scrollWidth)*.97)+'px';}}
function fitCanvas(){const stage=$('#canvas-stage');const style=getComputedStyle(stage);const w=stage.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight);const h=stage.clientHeight-parseFloat(style.paddingTop)-parseFloat(style.paddingBottom);const ratio=Math.max(.16,Math.min(w/1000,h/700))*zoom;const wrapper=$('#artboard-shell');wrapper.style.width=(1000*ratio)+'px';wrapper.style.height=(700*ratio)+'px';$('#artboard').style.transform=`scale(${ratio})`;$('#zoom-label').textContent=zoom===1?'Ajustar':Math.round(ratio*100)+'%';for(const thumb of $$('.thumbnail')){const art=$('.artboard',thumb);if(art)art.style.transform=`scale(${(thumb.clientWidth-6)/1000})`;}}
function renderThumbnails(){$('#sheet-strip').innerHTML=SHEETS.map((s,i)=>`<button class="sheet-button" data-sheet="${i}" aria-label="Ver lámina ${i+1}: ${s.name}" ${i===sheet?'aria-current="page"':''}><div class="thumbnail"><div class="artboard sheet-${s.id}" aria-hidden="true">${sheetHTML(i).replace(/<div class="scene-controls">[\s\S]*?<\/div>/g,'').replace(/ tabindex="0" role="button" aria-label="[^"]*"/g,'')}</div></div><div class="thumbnail-meta"><b>${String(i+1).padStart(2,'0')} &nbsp; ${s.short}</b><span>${i===sheet?'●':'○'}</span></div></button>`).join('');for(const art of $$('.thumbnail .artboard'))fitText(art);}
function renderBoard(previous=[]){finishTextDrag(true);const generation=++renderGeneration;applyTheme();const board=$('#artboard');for(const el of $$('.morph-target',board))cancelTextMorph(el);board.className='artboard sheet-'+SHEETS[sheet].id;board.dataset.textSurface=SHEETS[sheet].id;board.dataset.cardView=cardView;board.innerHTML=sheetHTML(sheet);renderLayoutToolbar();$('#sheet-title').textContent=SHEETS[sheet].name;$('#sheet-number').textContent=String(sheet+1).padStart(2,'0')+' / 05';if(selected?.type==='text')getSelectedNode()?.classList.add('selected');fitText(board);renderThumbnails();fitCanvas();if(previous.length&&project.motion.enabled){requestAnimationFrame(()=>{if(generation!==renderGeneration)return;const nodes=$$('.morph-target',board);nodes.forEach((el,i)=>{const from=previous.find(v=>v.instance===el.dataset.instance);if(from)void morphText(el,from.snapshot,{duration:project.motion.duration,enabled:true});});});}}
function setSheet(index){if(index===sheet)return;finishTextDrag(true);sheet=Math.max(0,Math.min(4,index));zoom=1;selected=null;addSurface=null;renderBoard();if(panel==='content')renderPanel();}
function roleOptions(current){return ROLES.map(r=>`<option value="${r}" ${current===r?'selected':''}>${ROLE_NAMES[r]}</option>`).join('');}
function fontWeights(family){const catalog=allFonts().find(f=>f.family===family);return catalog?.weights?.length?catalog.weights:[400];}
function renderCardPalette(){return `<div class="panel-divider"></div><section class="panel-section card-palette" id="card-background-settings"><h3 class="section-label">Fondos de tarjetas <small>Independientes</small></h3><p class="section-description">Elegí cada cara por separado. Podés usar el mismo color en ambas.</p>${CARD_FACES.map(face=>`<div class="card-color-row"><label class="color-preview card-color-swatch" style="background:${resolveCardBackground(project,face)}"><input type="color" aria-label="Color de fondo · ${CARD_FACE_NAMES[face]}" data-card-color="${face}" value="${resolveCardBackground(project,face)}"></label><div class="color-info"><label for="card-hex-${face}">${CARD_FACE_NAMES[face]}</label><input id="card-hex-${face}" class="hex-input" aria-label="Código hexadecimal del ${CARD_FACE_NAMES[face].toLocaleLowerCase('es')}" data-card-hex="${face}" value="${resolveCardBackground(project,face)}" maxlength="7" spellcheck="false"><small data-card-mode="${face}">${ROLES.includes(project.cardBackgrounds[face])?'Color '+COLOR_NAMES[project.cardBackgrounds[face]].toLocaleLowerCase('es'):'Personalizado'}</small></div><button class="card-palette-reset" data-card-reset="${face}" aria-label="Usar paleta en el ${CARD_FACE_NAMES[face].toLocaleLowerCase('es')}" ${project.cardBackgrounds[face]===DEFAULT_PROJECT.cardBackgrounds[face]?'disabled':''}>Usar paleta</button></div>`).join('')}<label class="card-contrast-control"><input id="card-auto-contrast" type="checkbox" ${project.cardAutoContrast?'checked':''}>Adaptar textos al fondo</label><p class="selected-info">En fondos personalizados, ajusta los textos que pierden contraste. Desactivalo para conservar exactamente sus colores.</p></section>`;}
function renderPalette(){return `<section class="panel-section"><h3 class="section-label">Paleta de marca <small>3 colores</small></h3><p class="section-description">Un cambio se refleja en todas las láminas.</p>${ROLES.map((role,i)=>`<div class="color-row"><label class="color-preview" style="background:${project.palette[role]}" title="Elegir color ${COLOR_NAMES[role].toLowerCase()}"><input type="color" aria-label="Color ${COLOR_NAMES[role].toLowerCase()}" data-color="${role}" value="${project.palette[role]}"></label><div class="color-info"><label for="hex-${role}">${COLOR_NAMES[role]}</label><input class="hex-input" id="hex-${role}" aria-label="Código hexadecimal ${COLOR_NAMES[role].toLowerCase()}" data-hex="${role}" value="${project.palette[role]}" maxlength="7" spellcheck="false"></div><span class="color-number">0${i+1}</span></div>`).join('')}</section>${renderCardPalette()}<div class="panel-divider"></div><section class="panel-section"><h3 class="section-label">Puntos de partida <small>Paletas</small></h3><div class="preset-grid">${PRESETS.map((p,i)=>`<button class="preset" data-preset="${i}" aria-label="Aplicar paleta ${p.name}" aria-pressed="${ROLES.every(r=>p.palette[r]===project.palette[r])}"><span class="preset-colors">${ROLES.map(r=>`<i style="background:${p.palette[r]}"></i>`).join('')}</span><small>${p.name}</small></button>`).join('')}</div></section><div class="panel-divider"></div><section class="panel-section"><h3 class="section-label">Contraste y equilibrio</h3><div class="contrast-example" style="background:${project.palette.primary};color:${project.palette.secondary}"><strong>Aa</strong><span>Principal + secundario <i style="width:18px;height:3px;background:${project.palette.tertiary}"></i></span></div><div class="contrast-info"><span>Contraste de lectura</span><b id="contrast-ratio">${contrastRatio(project.palette.primary,project.palette.secondary).toFixed(1)} : 1</b></div></section><div class="subtle-note"><span class="note-icon">↗</span>Probá una paleta y recorré las aplicaciones. Tu identidad cambia con vos.</div>`;}
function renderFonts(){return ROLES.map((r,i)=>{const f=project.fonts[r];return `<section class="font-role-card"><div class="role-heading"><strong>0${i+1} / ${ROLE_NAMES[r]}</strong><span>${i===0?'Marca y titulares':i===1?'Lectura y subtítulos':'Datos y documentación'}</span></div><button class="font-picker-button" data-pick-font="${r}" aria-label="Elegir tipografía ${ROLE_NAMES[r].toLowerCase()}"><span>${esc(f.family)}</span><span>⌄</span></button><div class="font-role-sample" style="font-family:${esc(JSON.stringify(f.family))};font-weight:${f.weight}">${i===2?'Proyecto / 024':'Aa · Wertbau'}</div><div class="field-row"><label class="field-label">Peso<select class="field" data-font-weight="${r}" aria-label="Peso ${ROLE_NAMES[r].toLowerCase()}">${fontWeights(f.family).map(w=>`<option value="${w}" ${w===f.weight?'selected':''}>${w}${w===400?' · Regular':w===700?' · Bold':''}</option>`).join('')}</select></label><label class="field-label">Espaciado<input class="field" type="number" data-font-tracking="${r}" aria-label="Espaciado ${ROLE_NAMES[r].toLowerCase()}" min="-4" max="10" step=".1" value="${f.tracking}"></label></div></section>`;}).join('')+`<section class="panel-section"><h3 class="section-label">Forma del nombre</h3><select class="field" id="case-mode" aria-label="Mayúsculas o minúsculas de la marca"><option value="uppercase" ${project.caseMode==='uppercase'?'selected':''}>WERTBAU · Mayúsculas</option><option value="lowercase" ${project.caseMode==='lowercase'?'selected':''}>wertbau · Minúsculas</option><option value="original" ${project.caseMode==='original'?'selected':''}>Conservar el texto escrito</option></select></section><section class="panel-section"><button class="upload-button" data-action="upload-font"><strong>＋</strong>Cargar mis tipografías<small>OTF, TTF, WOFF, WOFF2 · hasta 8 MB c/u</small></button><p class="selected-info">${FONT_CATALOG.length} familias incluidas + Inter y Cascadia Mono. ${project.customFonts.length?project.customFonts.length+' fuentes propias cargadas.':'Podés sumar las fuentes de tu entrega.'}</p></section><div class="subtle-note">La referencia usa Söhne Breit. Hasta cargar ese archivo, la base editable usa Space Grotesk.</div>`;}
function addTextControls(){return `<section class="add-text-section"><label class="field-label" for="text-surface">Agregar texto en</label><select id="text-surface" class="field text-surface-select">${SHEET_SURFACES[sheet].map(surface=>`<option value="${surface}" ${surface===currentAddSurface()?'selected':''}>${esc(SURFACE_NAMES[surface])}</option>`).join('')}</select><button class="button outline wide" data-action="add-text" ${project.customTexts.length>=100?'disabled':''}>＋ Agregar cuadro de texto</button></section>`;}
function renderContent(){
  if(selected?.type==='text'&&!textData(selected.key))selected=null;
  if(!selected){
    const nodes=$$('[data-instance]',$('#artboard')).filter(node=>node.offsetParent!==null);
    return `${addTextControls()}<div class="content-empty"><span class="eyebrow">CADA DETALLE, TUYO</span><h3>Elegí qué querés cambiar.</h3><p>Arrastrá los textos para ubicarlos. Hacé clic para cambiar el contenido o doble clic para escribir sobre la lámina.</p><div class="content-list">${nodes.map(node=>`<button class="content-item" data-select-text="${node.dataset.key}" data-select-instance="${node.dataset.instance}"><span>T</span><span>${esc(textLabel(node.dataset.key))}<small>${esc(SURFACE_NAMES[node.dataset.surface])}</small></span></button>`).join('')}${SHEETS[sheet].image?`<button class="content-item" data-select-image="${SHEETS[sheet].image}"><span>▧</span><span>Imagen de fondo</span></button>`:''}<button class="content-item" data-select-image="logo"><span>▧</span><span>Logotipo / imagen propia</span></button></div></div>`;
  }
  if(selected.type==='text'){
    const t=textData(selected.key),custom=!!t.id,position=project.placements[selected.instance]||{x:0,y:0};
    const surface=selected.instance?.split(':')[0];
    return `<div class="selected-content"><div class="selected-label"><span>${custom?'CUADRO NUEVO':'TEXTO SELECCIONADO'}</span><button data-action="deselect" aria-label="Quitar selección">×</button></div><section class="panel-section"><label class="field-label" for="text-editor">${esc(textLabel(selected.key))}</label><textarea id="text-editor" class="field text-editor" maxlength="5000">${esc(t.value)}</textarea><p class="selected-info">${custom||selected.key==='cardBackBrand'?'Este cuadro pertenece a '+esc(SURFACE_NAMES[surface]?.toLocaleLowerCase('es'))+'.':'El contenido es compartido. La posición se ajusta solo en '+esc(SURFACE_NAMES[surface]?.toLocaleLowerCase('es'))+'.'}</p></section><div class="field-row"><label class="field-label">Tipografía<select class="field" id="text-role">${roleOptions(t.role)}</select></label><label class="field-label">Color<select class="field" id="text-color">${ROLES.map(r=>`<option value="${r}" ${r===t.color?'selected':''}>${COLOR_NAMES[r]}</option>`).join('')}</select></label></div><div class="range-heading"><label for="text-scale">Tamaño relativo</label><output id="text-scale-value">${Math.round(t.scale*100)}%</output></div><input id="text-scale" class="range-input" type="range" min=".4" max="2" step=".05" value="${t.scale}"><label class="field-label" style="margin-top:18px">Alineación</label><div class="align-buttons">${['left','center','right'].map((a,i)=>`<button data-text-align="${a}" aria-label="Alinear ${['a la izquierda','al centro','a la derecha'][i]}" aria-pressed="${t.align===a}">${['☰','≡','☰'][i]}</button>`).join('')}</div><div class="position-fields"><h3 class="section-label">${custom?'Posición del cuadro':'Desplazamiento del texto'}</h3><div class="field-row">${[['x','Horizontal'],['y','Vertical']].map(([axis,label])=>`<label class="field-label">${label}<input class="field" type="number" data-text-position="${axis}" aria-label="Posición ${label.toLocaleLowerCase('es')} del texto" min="${axis==='x'?-1000:-700}" max="${axis==='x'?1000:700}" step="1" value="${position[axis]}"></label>`).join('')}</div>${custom?`<label class="field-label" style="margin-top:12px">Ancho del cuadro<input class="field" id="text-width" type="number" min="24" max="1000" step="1" value="${t.width}"></label>`:''}<p class="text-position-helper">Arrastrá sobre la lámina o usá las flechas. Mayús + flechas mueve 10 px.</p><div class="position-actions"><button class="button outline small" data-action="reset-position">Restablecer posición</button></div></div><div class="text-box-actions">${custom?'<button class="button outline wide" data-action="delete-text">Eliminar cuadro</button>':'<button class="button outline wide" data-action="reset-text">Restablecer texto</button>'}</div>${addTextControls()}</div>`;
  }
const slot=selected.key,d=project.images[slot];return `<div class="selected-content"><div class="selected-label"><span>${slot==='logo'?'LOGOTIPO':'IMAGEN DE FONDO'}</span><button data-action="deselect" aria-label="Quitar selección">×</button></div>${d.src?`<img class="image-preview" src="${esc(d.src)}" alt="${esc(d.alt)}">`:'<div class="no-image">▧</div>'}<button class="upload-button" data-action="upload-image"><strong>↑</strong>${d.src?'Reemplazar imagen':'Subir una imagen'}<small>PNG, JPG, WebP, GIF, SVG · hasta 8 MB</small></button><div class="image-tools"><button class="button outline small" data-action="reset-image">Original</button>${slot==='cards'||slot==='stationery'||slot==='logo'?'<button class="button outline small" data-action="remove-image">Quitar</button>':''}</div><label class="field-label" style="margin-top:18px">Descripción de la imagen<input class="field" id="image-alt" maxlength="500" value="${esc(d.alt)}"></label><label class="field-label" style="margin-top:14px">Ajuste<select class="field" id="image-fit"><option value="cover" ${d.fit==='cover'?'selected':''}>Cubrir el fondo</option><option value="contain" ${d.fit==='contain'?'selected':''}>Mostrar imagen completa</option></select></label>${[['x','Posición horizontal',0,100,1],['y','Posición vertical',0,100,1],['zoom','Escala',1,3,.05]].map(([key,label,min,max,step])=>`<div class="range-heading"><label for="image-${key}">${label}</label><output>${key==='zoom'?Math.round(d[key]*100):d[key]}%</output></div><input class="range-input" id="image-${key}" data-image-prop="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${d[key]}">`).join('')}<p class="selected-info">Las capas de marca permanecen editables sobre la imagen. Los textos que ya formen parte de una foto deben reemplazarse en esa foto.</p></div>`;}
function renderPanel(){const target=$('#editor-panel');if(target.dataset.activePanel!==panel){target.scrollTop=0;target.dataset.activePanel=panel;}$$('.panel-tabs button').forEach(el=>el.setAttribute('aria-selected',String(el.dataset.panel===panel)));$('#editor-panel').setAttribute('aria-labelledby','tab-'+panel);$('#editor-panel').innerHTML=panel==='palette'?renderPalette():panel==='fonts'?renderFonts():renderContent();}
function selectContent(type,key,instance,scroll=true){
  if(type==='text'&&!textData(key)||type==='image'&&!project.images[key])return;
  if(type==='text'){
    const nodes=$$(`[data-key="${CSS.escape(key)}"]`,$('#artboard'));
    const node=instance?nodes.find(el=>el.dataset.instance===instance):nodes.find(el=>el.offsetParent!==null)||nodes[0];
    if(!node)return;instance=node.dataset.instance;
    if(node.dataset.surface==='cards-front'||node.dataset.surface==='cards-back')activeCardFace=node.dataset.surface===CARD_SURFACES.front?'front':'back';
    addSurface=node.dataset.surface;
  }
  selected={type,key,...(instance?{instance}:{})};panel='content';renderPanel();
  for(const el of $$('.text-node',$('#artboard')))el.classList.toggle('selected',type==='text'&&el.dataset.instance===instance);
  if(scroll&&window.innerWidth<=800)$('#editor-panel').scrollIntoView({behavior:'smooth',block:'nearest'});
}
function localTextBox(node,surface){
  let x=0,y=0,current=node;
  while(current&&current!==surface){x+=current.offsetLeft||0;y+=current.offsetTop||0;current=current.offsetParent;}
  return {x,y,width:node.offsetWidth,height:node.offsetHeight};
}
function ancestorMatrix(node){
  let matrix=new DOMMatrix();
  for(let parent=node.parentElement;parent;parent=parent.parentElement){const transform=getComputedStyle(parent).transform;if(transform&&transform!=='none')matrix=new DOMMatrix(transform).multiply(matrix);}
  return matrix;
}
function geometryFor(node){const surface=getTextSurface(node);return {box:localTextBox(node,surface),bounds:{x:0,y:0,width:surface.clientWidth,height:surface.clientHeight}};}
function boundedPosition(node,position,geometry=geometryFor(node)){
  const value=clampOffset(position,geometry.box,geometry.bounds)||position;
  return {x:Math.round(Math.max(-1000,Math.min(1000,value.x))*10)/10,y:Math.round(Math.max(-700,Math.min(700,value.y))*10)/10};
}
function drawPosition(node,position){node.style.setProperty('--node-x',position.x+'px');node.style.setProperty('--node-y',position.y+'px');}
function updatePositionFields(position){for(const axis of ['x','y']){const field=$(`[data-text-position="${axis}"]`);if(field)field.value=position[axis];}}
function applySelectedPosition(position,{syncFields=true}={}){
  const node=getSelectedNode();if(!node)return;
  const next=boundedPosition(node,position);project.placements[selected.instance]=next;drawPosition(node,next);if(syncFields)updatePositionFields(next);renderThumbnails();fitCanvas();scheduleSave();
}
function finishTextDrag(cancelled=false){
  const state=dragState;if(!state)return;dragState=null;state.node.classList.remove('dragging');
  const board=$('#artboard');if(board.hasPointerCapture(state.pointerId))board.releasePointerCapture(state.pointerId);
  if(!state.moved)return;
  suppressCanvasClickUntil=performance.now()+300;
  if(cancelled){drawPosition(state.node,state.start);updatePositionFields(state.start);return;}
  checkpoint();project.placements[state.instance]=state.next;drawPosition(state.node,state.next);updatePositionFields(state.next);renderThumbnails();fitCanvas();scheduleSave();
}
function beginTextDrag(event){
  if(event.button!==0||document.body.classList.contains('presentation-mode')||modal.open)return;
  let node=event.target.closest('.text-node[data-instance]');if(!node||node.isContentEditable)return;
  const instance=node.dataset.instance;
  if(document.activeElement?.matches('input,textarea,select,[contenteditable=true]')){document.activeElement.blur();node=$(`[data-instance="${CSS.escape(instance)}"]`,$('#artboard'));if(!node)return;}
  finishTextDrag(true);cancelTextMorph(node);
  selectContent('text',node.dataset.key,instance,false);node.focus({preventScroll:true});
  const start={...(project.placements[instance]||{x:0,y:0})};
  dragState={node,instance,pointerId:event.pointerId,clientX:event.clientX,clientY:event.clientY,start,next:start,moved:false,matrix:ancestorMatrix(node),geometry:geometryFor(node)};
}
function moveTextDrag(event){
  const state=dragState;if(!state||event.pointerId!==state.pointerId)return;if(!(event.buttons&1)){finishTextDrag(true);return;}
  const dx=event.clientX-state.clientX,dy=event.clientY-state.clientY;
  if(!state.moved&&Math.hypot(dx,dy)<4)return;
  const delta=screenDeltaToLocal(dx,dy,state.matrix);if(!delta)return;
  event.preventDefault();if(!state.moved)$('#artboard').setPointerCapture(event.pointerId);state.moved=true;state.node.classList.add('dragging');
  state.next=boundedPosition(state.node,{x:state.start.x+delta.x,y:state.start.y+delta.y},state.geometry);
  drawPosition(state.node,state.next);updatePositionFields(state.next);
}

function contrastRatio(a,b){const luminance=h=>{const rgb=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255).map(n=>n<=.04045?n/12.92:((n+.055)/1.055)**2.4);return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722;};const l=[luminance(a),luminance(b)].sort((a,b)=>b-a);return (l[0]+.05)/(l[1]+.05);}

function openModal(title,subtitle,body,kind='default'){$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Cerrar ventana">×</button></div>${body}`;modal.dataset.kind=kind;if(!modal.open)modal.showModal();}
function closeModal(){fontPreviewObserver?.disconnect();fontPreviewObserver=null;modal.close();}
function allFonts(){const custom=project.customFonts.map(f=>({family:f.family,label:f.family,id:f.id,category:'custom',weights:[f.weight]}));return [...EXTRA_BASE_FONTS,...FONT_CATALOG,...custom];}
function showFontPicker(role){fontPickerRole=role;openModal('Encontrá el carácter de tu marca.',`${FONT_CATALOG.length} familias + Inter + Cascadia Mono + tus fuentes · Tipografía ${ROLE_NAMES[role].toLowerCase()}`,`<div class="modal-search"><input class="field" id="font-search" type="search" placeholder="Buscar una tipografía…" aria-label="Buscar tipografía"><select class="field" id="font-category" aria-label="Categoría de tipografía"><option value="all">Todas las familias</option><option value="sans">Sans serif</option><option value="serif">Serif</option><option value="mono">Monoespaciadas</option><option value="display">Display</option><option value="custom">Mis tipografías</option></select></div><div class="font-results" id="font-results"></div><div class="modal-foot">Las fuentes se cargan cuando las necesitás. Podés sumar las de tu entrega desde «Cargar mis tipografías».</div>`,'fonts');renderFontResults();$('#font-search').focus();}
function renderFontResults(){fontPreviewObserver?.disconnect();const query=($('#font-search')?.value||'').toLocaleLowerCase('es');const category=$('#font-category')?.value||'all';const fonts=allFonts().filter(f=>f.family.toLocaleLowerCase('es').includes(query)&&(category==='all'||f.category===category));$('#font-results').innerHTML=fonts.length?fonts.map(f=>`<button class="font-option" data-font-choice="${esc(f.family)}" aria-label="Usar ${esc(f.family)}" aria-pressed="${project.fonts[fontPickerRole].family===f.family}"><div class="font-option-top">${esc(f.family)}<small>${{sans:'Sans',serif:'Serif',mono:'Mono',display:'Display',custom:'Propia'}[f.category]}</small></div><div class="font-option-preview">${esc(displayText('brand')||'Wertbau')}</div></button>`).join(''):'<div class="empty-state">No hay fuentes con ese nombre. Probá otra búsqueda o cargá tu archivo.</div>';if(!('IntersectionObserver' in window))return;fontPreviewObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;fontPreviewObserver.unobserve(entry.target);const family=entry.target.dataset.fontChoice;loadFont(family,400).then(()=>{const preview=$('.font-option-preview',entry.target);if(preview){preview.style.fontFamily=JSON.stringify(family);entry.target.classList.add('loaded');}}).catch(()=>{});}},{root:$('#font-results'),rootMargin:'100px'});$$('.font-option',$('#font-results')).forEach(el=>fontPreviewObserver.observe(el));}
async function chooseFont(role,family,requestedWeight){const request=++fontRequests[role],epoch=projectEpoch;try{const active=$(`[data-font-choice="${CSS.escape(family)}"]`);if(active)active.setAttribute('aria-busy','true');const loaded=await loadFont(family,requestedWeight??project.fonts[role].weight);if(request!==fontRequests[role]||epoch!==projectEpoch)return;const previous=snapshots();checkpoint();project.fonts[role].family=family;project.fonts[role].weight=loaded.weight;closeModal();renderBoard(previous);renderPanel();scheduleSave();toast(`${ROLE_NAMES[role]}: ${family}`);}catch(error){toast(error.message,true);$$('[aria-busy]').forEach(el=>el.removeAttribute('aria-busy'));}}
async function showVariants(){openModal('Guardá cada posibilidad.','Tus versiones se conservan en este navegador.',`<div class="modal-body"><form class="variant-form" id="variant-form"><input class="field" id="variant-name" maxlength="100" placeholder="Nombre de la variante" aria-label="Nombre de la variante" value="${esc(project.name)}"><button class="button dark" type="submit">Guardar variante</button></form><div id="variant-list"><div class="empty-state">Cargando variantes…</div></div><button class="button outline wide" data-action="import-project" style="margin-top:18px">Importar un proyecto guardado</button></div>`,'variants');await refreshVariants();}
async function refreshVariants(){try{const variants=await listVariants();const container=$('#variant-list');if(!container)return;container.innerHTML=variants.length?variants.map(v=>`<div class="variant-row"><div class="variant-swatches">${ROLES.map(r=>`<i style="background:${v.project.palette[r]}"></i>`).join('')}</div><div class="variant-copy"><strong>${esc(v.name)}</strong><small>${esc(v.project.fonts.primary.family)} · ${new Date(v.updatedAt).toLocaleDateString('es-AR')}</small></div><button class="button outline small" data-load-variant="${esc(v.id)}">Abrir</button><button class="icon-button" data-delete-variant="${esc(v.id)}" aria-label="Eliminar variante ${esc(v.name)}">×</button></div>`).join(''):'<div class="empty-state">Tu primera exploración empieza acá.<br>Guardá una variante para volver a ella cuando quieras.</div>';}catch(error){toast(error.message,true);}}
async function restoreProject(raw,{history=true,notice='Proyecto abierto'}={}){const next=validateProject(raw);const token=++restoreRequest,epoch=++projectEpoch,version=mutationVersion;for(const r of ROLES)fontRequests[r]++;for(const f of next.customFonts)await registerCustomFont(f);await Promise.all(ROLES.map(async r=>{const loaded=await loadFont(next.fonts[r].family,next.fonts[r].weight);next.fonts[r].weight=loaded.weight;}));if(token!==restoreRequest||epoch!==projectEpoch)return false;if(version!==mutationVersion){toast('La restauración se canceló porque editaste el proyecto mientras se cargaba.');return false;}const previous=snapshots();if(history)checkpoint();project=next;selected=null;renderBoard(previous);renderPanel();scheduleSave();toast(notice);return true;}
async function loadVariant(id){try{const variants=await listVariants();const target=variants.find(v=>v.id===id);if(!target)throw new Error('La variante ya no está disponible.');await restoreProject(target.project,{notice:'Variante «'+target.name+'» abierta'});closeModal();}catch(error){toast(error.message,true);}}
function showExport(){openModal('Llevá tu identidad con vos.','Elegí cómo querés guardar esta exploración.',`<div class="modal-body"><button class="export-option" data-action="export-json"><span class="export-icon">{ }</span><span class="export-copy"><strong>Proyecto editable</strong><small>JSON con textos, imágenes, fuentes propias y ajustes. Volvé a importarlo.</small></span><span class="export-arrow">↓</span></button><button class="export-option" data-action="export-css"><span class="export-icon">#</span><span class="export-copy"><strong>Estilos de la marca</strong><small>Variables CSS de la paleta y las tres jerarquías tipográficas.</small></span><span class="export-arrow">↓</span></button><button class="export-option" data-action="print"><span class="export-icon">▤</span><span class="export-copy"><strong>Las cinco láminas en PDF</strong><small>Abre impresión. Elegí «Guardar como PDF», horizontal y sin márgenes.</small></span><span class="export-arrow">↗</span></button><button class="export-option" data-action="import-project"><span class="export-icon">↑</span><span class="export-copy"><strong>Abrir un proyecto</strong><small>Recuperá una exploración exportada desde cualquier equipo.</small></span><span class="export-arrow">↗</span></button><div class="subtle-note" style="margin-top:18px">El código de la aplicación y la configuración de cada exploración son independientes. Exportá el proyecto para trasladar también tus imágenes y fuentes importadas.</div></div>`,'export');}
function filename(){return (project.name||'vision-wertbau').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'vision-wertbau';}
function downloadFile(content,type,name){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportJSON(){await flushSave();downloadFile(JSON.stringify(validateProject(project),null,2),'application/json',filename()+'.json');toast('Proyecto editable exportado.');}
function exportCSS(){const lines=['/* Vision Wertbau — estilos de marca */','/* Cargá las familias indicadas antes de usar estas variables. */',':root {'];for(const role of ROLES)lines.push(`  --brand-${role}: ${project.palette[role]};`);for(const [name,value] of cardThemeVariables())lines.push(`  ${name}: ${value};`);for(const role of ROLES){const f=project.fonts[role];lines.push(`  --font-${role}: ${JSON.stringify(f.family)}, ${role==='tertiary'?'monospace':'sans-serif'};`,`  --weight-${role}: ${f.weight};`,`  --tracking-${role}: ${f.tracking}px;`);}lines.push('}','');downloadFile(lines.join('\n'),'text/css',filename()+'-estilos.css');toast('Estilos CSS exportados.');}
async function printSheets(){closeModal();await document.fonts.ready;const root=$('#print-root');root.innerHTML=SHEETS.map((s,i)=>`<section class="print-page"><div class="artboard sheet-${s.id}">${sheetHTML(i)}</div></section>`).join('');root.setAttribute('aria-hidden','false');root.style.display='block';root.style.position='fixed';root.style.left='-10000px';for(const art of $$('.artboard',root))fitText(art);await Promise.all($$('img',root).map(img=>img.decode().catch(()=>{})));root.removeAttribute('style');window.print();root.setAttribute('aria-hidden','true');}
function showHelp(){openModal('Tu identidad, sin salir del navegador.','Una guía breve para empezar.',`<div class="modal-body"><div class="help-grid"><div class="help-item"><h3>01 / Colores</h3><p>Elegí los tres colores de tu sistema. Se aplican a tarjetas, papelería, cartel y fachada. En Tarjetas podés elegir el fondo del frente y del dorso por separado, incluso blanco y blanco.</p></div><div class="help-item"><h3>02 / Tipografías</h3><p>Explorá las 100 familias incluidas, ajustá peso y espaciado o cargá tus archivos de la entrega.</p></div><div class="help-item"><h3>03 / Textos e imágenes</h3><p>Arrastrá los cuadros para moverlos. Doble clic para escribir. Usá Agregar texto para sumar cuadros y Frente / Dorso / Ambas para alternar las tarjetas. En Contenido elegís la superficie donde se agrega cada cuadro.</p></div><div class="help-item"><h3>04 / Conservá tus versiones</h3><p>Usá Variantes para comparar propuestas. Exportá el proyecto JSON para llevarlo a otro navegador o equipo.</p></div></div><div class="panel-divider"></div><p class="reference-note">La plantilla toma como referencia el PDF WERTBAU 01A. Sus fotografías estaban aplanadas; las áreas de marca se recrearon como capas editables. Söhne Breit se podrá usar al cargar su archivo tipográfico.</p><button class="button outline wide" data-action="reset-project" style="margin-top:20px">Volver al proyecto inicial (se puede deshacer)</button></div>`,'help');}
function readFileData(file,type){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('No se pudo leer el archivo.'));reader.onload=()=>{let value=String(reader.result);if(type&&value.startsWith('data:;'))value=value.replace('data:;',`data:${type};`);resolve(value);};reader.readAsDataURL(file);});}
async function uploadImage(file){if(!file)return;const slot=pendingImageSlot,epoch=projectEpoch;try{if(file.size>8*1024*1024)throw new Error('La imagen supera 8 MB. Exportá una versión más liviana.');if(!/\.(png|jpe?g|webp|gif|svg)$/i.test(file.name))throw new Error('Usá PNG, JPG, WebP, GIF o SVG.');const mime=file.name.toLowerCase().endsWith('.svg')?'image/svg+xml':undefined;const dataUrl=await readFileData(file,mime);const next=cloneProject(project);next.images[slot]={...next.images[slot],src:dataUrl,x:50,y:50,zoom:1};validateProject(next);await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{if(img.naturalWidth>12000||img.naturalHeight>12000)reject(new Error('La imagen es demasiado grande. Reducila a menos de 12000 px.'));else resolve();};img.onerror=()=>reject(new Error('El navegador no pudo abrir la imagen.'));img.src=dataUrl;});if(epoch!==projectEpoch)return;checkpoint();const current=cloneProject(project);current.images[slot]={...current.images[slot],src:dataUrl,x:50,y:50,zoom:1};project=validateProject(current);renderBoard();renderPanel();scheduleSave();toast('Imagen actualizada.');}catch(error){toast(error.message,true);}finally{$('#image-file').value='';}}
async function uploadFonts(files){const list=[...files];if(!list.length)return;const epoch=projectEpoch;let added=0;checkpoint();for(const file of list){try{if(project.customFonts.length>=64)throw new Error('Llegaste a 64 fuentes propias en este proyecto.');if(file.size>8*1024*1024)throw new Error('La fuente supera 8 MB.');const extension=file.name.split('.').at(-1).toLowerCase();if(!['woff2','woff','ttf','otf'].includes(extension))throw new Error('Formato no compatible.');let family=file.name.replace(/\.(woff2?|ttf|otf)$/i,'').replace(/[_-]/g,' ').replace(/["\\\x00-\x1f]/g,'').trim().slice(0,90)||'Mi tipografía';if(allFonts().some(f=>f.family===family))family+=' '+(project.customFonts.length+1);const weight=/bold|kräftig|kraftig|700/i.test(family)?700:/medium|500/i.test(family)?500:/light|300/i.test(family)?300:400;const custom={id:'font-'+crypto.randomUUID(),family,dataUrl:await readFileData(file,'font/'+extension),weight};const next=cloneProject(project);next.customFonts.push(custom);validateProject(next);await registerCustomFont(custom);if(epoch!==projectEpoch)break;const current=cloneProject(project);current.customFonts.push(custom);project=validateProject(current);added++;}catch(error){toast(file.name+': '+error.message,true);}}if(added){scheduleSave();renderPanel();toast(`${added} tipografía${added>1?'s':''} propia${added>1?'s':''} disponible${added>1?'s':''}. Elegila en el catálogo.`);}$('#font-file').value='';}
async function importProject(file){if(!file)return;try{if(file.size>45*1024*1024)throw new Error('El archivo supera 45 MB.');const data=JSON.parse(await file.text());await restoreProject(data,{notice:'Proyecto importado correctamente.'});closeModal();}catch(error){toast('No se pudo importar: '+error.message,true);}finally{$('#project-file').value='';}}
async function historyMove(direction){const source=direction==='undo'?undoStack:redoStack;const destination=direction==='undo'?redoStack:undoStack;const live=JSON.stringify(project);while(source.at(-1)===live)source.pop();if(!source.length){updateHistoryButtons();return;}const raw=JSON.parse(source.at(-1));try{const current=JSON.stringify(project);const restored=await restoreProject(raw,{history:false,notice:direction==='undo'?'Cambio deshecho.':'Cambio recuperado.'});if(restored===false)return;source.pop();destination.push(current);updateHistoryButtons();}catch(error){toast(error.message,true);}}

const actions={
  'close-modal':closeModal,
  'add-text':addText,
  'card-colors':()=>{panel='palette';renderPanel();$('#card-background-settings').scrollIntoView({block:'nearest'});$('#card-hex-'+activeCardFace).focus({preventScroll:true});},
  'delete-text':deleteSelectedText,
  'reset-position':()=>{if(selected?.type!=='text')return;checkpoint();delete project.placements[selected.instance];renderBoard();renderPanel();scheduleSave();},
  variants:showVariants,
  export:showExport,
  help:showHelp,
  'export-json':exportJSON,
  'export-css':exportCSS,
  print:printSheets,
  'import-project':()=>$('#project-file').click(),
  'upload-font':()=>$('#font-file').click(),
  'upload-image':()=>{pendingImageSlot=selected?.type==='image'?selected.key:SHEETS[sheet].image||'logo';$('#image-file').click();},
  'zoom-in':()=>{zoom=Math.min(2.5,zoom+.15);fitCanvas();},
  'zoom-out':()=>{zoom=Math.max(.5,zoom-.15);fitCanvas();},
  'zoom-fit':()=>{zoom=1;fitCanvas();},
  present:()=>{document.body.classList.toggle('presentation-mode');zoom=1;requestAnimationFrame(fitCanvas);},
  motion:()=>{checkpoint();project.motion.enabled=!project.motion.enabled;applyTheme();scheduleSave();toast(project.motion.enabled?'Transición morfológica activada.':'Transición desactivada.');},
  undo:()=>historyMove('undo'),
  redo:()=>historyMove('redo'),
  reference:()=>openModal('La referencia original.',`WERTBAU 01A · Lámina ${sheet+1} de 5`,`<div class="modal-body"><img class="reference-img" src="./assets/reference-0${sheet+1}.png" alt="Lámina ${sheet+1} del PDF original WERTBAU"><p class="reference-note">Esta es la lámina del PDF que compartiste. El editor reconstruye sus elementos como capas para que puedas cambiar la identidad en tiempo real.</p></div>`,'reference'),
  deselect:()=>{selected=null;renderPanel();$$('.text-node.selected').forEach(e=>e.classList.remove('selected'));},
  'reset-text':()=>{if(selected?.type!=='text')return;checkpoint();const old=snapshots();project.texts[selected.key]=cloneProject(DEFAULT_PROJECT.texts[selected.key]);renderBoard(old);renderPanel();scheduleSave();},
  'reset-image':()=>{if(selected?.type!=='image')return;checkpoint();project.images[selected.key]=cloneProject(DEFAULT_PROJECT.images[selected.key]);renderBoard();renderPanel();scheduleSave();},
  'remove-image':()=>{if(selected?.type!=='image')return;checkpoint();project.images[selected.key].src='';renderBoard();renderPanel();scheduleSave();},
  'reset-project':async()=>{await restoreProject(DEFAULT_PROJECT,{notice:'Proyecto inicial restaurado. Podés deshacer el cambio.'});closeModal();}
};
document.addEventListener('click',event=>{const target=event.target.closest('button,[data-key],[data-image]');if(!target)return;const sheetButton=target.closest('[data-sheet]');if(sheetButton){setSheet(Number(sheetButton.dataset.sheet));return;}if(target.dataset.cardReset){checkpoint();setCardBackground(target.dataset.cardReset,DEFAULT_PROJECT.cardBackgrounds[target.dataset.cardReset]);return;}if(target.dataset.cardView){setCardView(target.dataset.cardView);return;}if(target.dataset.panel){panel=target.dataset.panel;renderPanel();return;}if(target.dataset.action){const fn=actions[target.dataset.action];if(fn)Promise.resolve(fn()).catch(error=>toast(error.message,true));return;}if(target.dataset.preset!==undefined){checkpoint();project.palette={...PRESETS[Number(target.dataset.preset)].palette};renderBoard();renderPanel();scheduleSave();return;}if(target.dataset.pickFont){showFontPicker(target.dataset.pickFont);return;}if(target.dataset.fontChoice){void chooseFont(fontPickerRole,target.dataset.fontChoice);return;}if(target.dataset.selectText){selectContent('text',target.dataset.selectText,target.dataset.selectInstance);return;}if(target.dataset.selectImage){selectContent('image',target.dataset.selectImage);return;}if(target.dataset.loadVariant){void loadVariant(target.dataset.loadVariant);return;}if(target.dataset.deleteVariant){void deleteVariant(target.dataset.deleteVariant).then(()=>{toast('Variante eliminada.');return refreshVariants();}).catch(e=>toast(e.message,true));return;}if(target.dataset.textAlign&&selected?.type==='text'){checkpoint();textData(selected.key).align=target.dataset.textAlign;renderBoard();renderPanel();scheduleSave();return;}if(document.body.classList.contains('presentation-mode')||performance.now()<suppressCanvasClickUntil)return;if(target.dataset.key&&target.closest('#artboard'))selectContent('text',target.dataset.key,target.dataset.instance);else if(target.dataset.image&&target.closest('#artboard'))selectContent('image',target.dataset.image);});

$('#artboard').addEventListener('pointerdown',beginTextDrag);
$('#artboard').addEventListener('pointermove',moveTextDrag);
$('#artboard').addEventListener('pointerup',event=>{if(event.pointerId===dragState?.pointerId)finishTextDrag();});
$('#artboard').addEventListener('pointercancel',event=>{if(event.pointerId===dragState?.pointerId)finishTextDrag(true);});
$('#artboard').addEventListener('lostpointercapture',event=>{if(event.pointerId===dragState?.pointerId)finishTextDrag(true);});
document.addEventListener('pointerup',event=>{if(event.pointerId===dragState?.pointerId)finishTextDrag();});
document.addEventListener('pointercancel',event=>{if(event.pointerId===dragState?.pointerId)finishTextDrag(true);});
window.addEventListener('blur',()=>finishTextDrag(true));
$('#artboard').addEventListener('dblclick',event=>{const el=event.target.closest('[data-key]');if(!el||document.body.classList.contains('presentation-mode')||performance.now()<suppressCanvasClickUntil)return;finishTextDrag(true);cancelTextMorph(el);checkpoint();el.contentEditable='true';el.setAttribute('role','textbox');el.setAttribute('aria-label',textLabel(el.dataset.key));el.textContent=textData(el.dataset.key).value;el.focus();const range=document.createRange();range.selectNodeContents(el);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);});
$('#artboard').addEventListener('input',event=>{const el=event.target.closest('[contenteditable=true]');if(!el)return;textData(el.dataset.key).value=el.innerText.slice(0,5000);if(selected?.key===el.dataset.key&&$('#text-editor'))$('#text-editor').value=textData(el.dataset.key).value;scheduleSave();});
$('#artboard').addEventListener('paste',event=>{if(!event.target.closest('[contenteditable=true]'))return;event.preventDefault();const text=event.clipboardData.getData('text/plain').slice(0,5000);const selection=window.getSelection();if(selection?.rangeCount){const range=selection.getRangeAt(0);range.deleteContents();const node=document.createTextNode(text);range.insertNode(node);range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);event.target.dispatchEvent(new Event('input',{bubbles:true}));}});
$('#artboard').addEventListener('focusout',event=>{
  const target=event.target;if(target.contentEditable!=='true')return;
  target.contentEditable='false';target.setAttribute('role','button');
  for(const node of $$(`[data-key="${CSS.escape(target.dataset.key)}"]`,$('#artboard'))){
    node.textContent=displayText(node.dataset.key);node.setAttribute('aria-label','Editar '+textLabel(node.dataset.key)+' · '+SURFACE_NAMES[node.dataset.surface]);
  }
  fitText($('#artboard'));renderThumbnails();fitCanvas();
});
document.addEventListener('focusin',event=>{const el=event.target;if(el.matches('input,textarea,select')&&!el.closest('#modal')&&!['image-file','font-file','project-file'].includes(el.id))checkpoint();});

document.addEventListener('input',event=>{const el=event.target;
if(el.dataset.cardColor){setCardBackground(el.dataset.cardColor,el.value.toUpperCase());return;}
if(el.dataset.cardHex){if(/^#?[0-9a-f]{6}$/i.test(el.value.trim()))setCardBackground(el.dataset.cardHex,hexColor(el.value));return;}
if(el.dataset.textPosition&&selected?.type==='text'){
  const value=Number(el.value),axis=el.dataset.textPosition,max=axis==='x'?1000:700;
  if(el.value.trim()&&Number.isFinite(value)&&value>=-max&&value<=max)applySelectedPosition({...(project.placements[selected.instance]||{x:0,y:0}),[axis]:value},{syncFields:false});
  return;
}
if(el.id==='text-width'&&selected?.type==='text'&&textData(selected.key)?.id){
  const value=Number(el.value);if(Number.isFinite(value)&&value>=24&&value<=1000){textData(selected.key).width=value;renderBoard();scheduleSave();}return;
}
if(el.id==='font-search'){renderFontResults();return;}if(el.dataset.color){const role=el.dataset.color;project.palette[role]=el.value.toUpperCase();applyTheme();el.closest('.color-preview').style.background=el.value;$('#hex-'+role).value=project.palette[role];const example=$('.contrast-example');if(example){example.style.background=project.palette.primary;example.style.color=project.palette.secondary;$('i',example).style.background=project.palette.tertiary;$('#contrast-ratio').textContent=contrastRatio(project.palette.primary,project.palette.secondary).toFixed(1)+' : 1';}scheduleSave();return;}if(el.id==='project-name'){project.name=el.value||'Sin título';scheduleSave();return;}if(el.id==='text-editor'&&selected?.type==='text'){const previous=['brand','cardBackBrand','tagline','projectCode','planCode'].includes(selected.key)?snapshots():[];textData(selected.key).value=el.value;renderBoard(previous);scheduleSave();return;}if(el.id==='text-scale'&&selected?.type==='text'){textData(selected.key).scale=Number(el.value);$('#text-scale-value').textContent=Math.round(Number(el.value)*100)+'%';renderBoard();scheduleSave();return;}if(el.dataset.imageProp&&selected?.type==='image'){project.images[selected.key][el.dataset.imageProp]=Number(el.value);const output=el.previousElementSibling?.querySelector('output');if(output)output.textContent=(el.dataset.imageProp==='zoom'?Math.round(Number(el.value)*100):el.value)+'%';renderBoard();scheduleSave();return;}if(el.id==='image-alt'&&selected?.type==='image'){project.images[selected.key].alt=el.value;renderBoard();scheduleSave();}});

document.addEventListener('change',event=>{const el=event.target;
if(el.dataset.cardHex){const value=hexColor(el.value);if(!value){toast('Ingresá un color hexadecimal válido, por ejemplo #FFFFFF.',true);el.value=resolveCardBackground(project,el.dataset.cardHex);return;}el.value=value;setCardBackground(el.dataset.cardHex,value);return;}
if(el.id==='card-auto-contrast'){project.cardAutoContrast=el.checked;applyCardTheme();scheduleSave();return;}
if(el.id==='text-surface'){addSurface=el.value;return;}
if(el.dataset.textPosition&&selected?.type==='text'){
  const value=Number(el.value),axis=el.dataset.textPosition,max=axis==='x'?1000:700;
  if(!el.value.trim()||!Number.isFinite(value)||value< -max||value>max){toast('Ingresá una posición entre '+(-max)+' y '+max+'.',true);renderPanel();return;}
  const position={...(project.placements[selected.instance]||{x:0,y:0}),[axis]:value};
  applySelectedPosition(position);return;
}
if(el.id==='text-width'&&selected?.type==='text'&&textData(selected.key)?.id){
  const value=Number(el.value);if(!Number.isFinite(value)||value<24||value>1000){toast('El ancho debe estar entre 24 y 1000 px.',true);el.value=textData(selected.key).width;return;}
  textData(selected.key).width=value;renderBoard();scheduleSave();return;
}
if(el.dataset.hex){let value=el.value.trim();if(!value.startsWith('#'))value='#'+value;if(/^#[0-9a-f]{3}$/i.test(value))value='#'+[...value.slice(1)].map(c=>c+c).join('');if(!/^#[0-9a-f]{6}$/i.test(value)){toast('Ingresá un color hexadecimal válido, por ejemplo #4473A7.',true);el.value=project.palette[el.dataset.hex];return;}project.palette[el.dataset.hex]=value.toUpperCase();renderBoard();renderPanel();scheduleSave();return;}if(el.dataset.fontWeight){void chooseFont(el.dataset.fontWeight,project.fonts[el.dataset.fontWeight].family,Number(el.value));return;}if(el.dataset.fontTracking){const val=Number(el.value);if(!Number.isFinite(val)||val< -4||val>10){el.value=project.fonts[el.dataset.fontTracking].tracking;return;}const previous=snapshots();project.fonts[el.dataset.fontTracking].tracking=val;renderBoard(previous);scheduleSave();return;}if(el.id==='case-mode'){const previous=snapshots();project.caseMode=el.value;renderBoard(previous);scheduleSave();return;}if(el.id==='font-category'){renderFontResults();return;}if((el.id==='text-role'||el.id==='text-color')&&selected?.type==='text'){const previous=snapshots();textData(selected.key)[el.id==='text-role'?'role':'color']=el.value;renderBoard(previous);scheduleSave();return;}if(el.id==='image-fit'&&selected?.type==='image'){project.images[selected.key].fit=el.value;renderBoard();scheduleSave();return;}if(el.id==='image-file'){void uploadImage(el.files[0]);return;}if(el.id==='font-file'){void uploadFonts(el.files);return;}if(el.id==='project-file')void importProject(el.files[0]);});

document.addEventListener('submit',event=>{if(event.target.id!=='variant-form')return;event.preventDefault();const name=$('#variant-name').value.trim();if(!name){toast('Escribí un nombre para esta variante.',true);return;}void saveVariant(project,name).then(()=>{toast('Variante guardada.');return refreshVariants();}).catch(e=>toast(e.message,true));});
document.addEventListener('keydown',event=>{
  const editing=event.target.matches('input,textarea,select,[contenteditable=true]');
  if(event.key==='Escape'){
    finishTextDrag(true);
    if(document.body.classList.contains('presentation-mode')){document.body.classList.remove('presentation-mode');fitCanvas();}
    if(event.target.contentEditable==='true')event.target.blur();return;
  }
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();void exportJSON();return;}
  if(!editing&&(event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();finishTextDrag(true);void historyMove(event.shiftKey?'redo':'undo');return;}
  const node=event.target.closest('#artboard .text-node[data-instance]');
  if(!editing&&!modal.open&&!document.body.classList.contains('presentation-mode')&&node&&!event.ctrlKey&&!event.metaKey&&!event.altKey){
    if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){
      event.preventDefault();if(selected?.instance!==node.dataset.instance)selectContent('text',node.dataset.key,node.dataset.instance,false);
      if(!event.repeat)checkpoint();const step=event.shiftKey?10:1,position={...(project.placements[node.dataset.instance]||{x:0,y:0})};
      if(event.key==='ArrowLeft')position.x-=step;if(event.key==='ArrowRight')position.x+=step;if(event.key==='ArrowUp')position.y-=step;if(event.key==='ArrowDown')position.y+=step;
      applySelectedPosition(position);return;
    }
    if(event.key==='Enter'){event.preventDefault();selectContent('text',node.dataset.key,node.dataset.instance);$('#text-editor')?.focus();return;}
    if((event.key==='Delete'||event.key==='Backspace')&&textData(node.dataset.key)?.id){event.preventDefault();selectContent('text',node.dataset.key,node.dataset.instance,false);deleteSelectedText();return;}
  }
  if(!editing&&!modal.open&&event.key==='ArrowRight'){event.preventDefault();setSheet((sheet+1)%5);}
  if(!editing&&!modal.open&&event.key==='ArrowLeft'){event.preventDefault();setSheet((sheet+4)%5);}
});
modal.addEventListener('click',event=>{if(event.target===modal)closeModal();});
modal.addEventListener('close',()=>fontPreviewObserver?.disconnect());
window.addEventListener('resize',fitCanvas);
window.addEventListener('pagehide',()=>void flushSave());
document.addEventListener('visibilitychange',()=>{if(document.hidden)void flushSave();});
new ResizeObserver(fitCanvas).observe($('#canvas-stage'));

async function init(){try{const saved=await readSavedProject();if(saved)project=saved;}catch(error){toast(error.message,true);}applyTheme();renderBoard();renderPanel();try{for(const font of project.customFonts)await registerCustomFont(font);const results=await Promise.allSettled(ROLES.map(r=>loadFont(project.fonts[r].family,project.fonts[r].weight)));const failures=results.filter(r=>r.status==='rejected');renderBoard();if(failures.length)toast('Alguna fuente no pudo cargarse. Elegí otra familia o volvé a cargar su archivo.',true);}catch(error){toast(error.message,true);}updateHistoryButtons();}
void init();
